// dataFetcher.js
const axios = require('axios');
const cheerio = require('cheerio');

const DEFAULT_URL = 'https://en.wikipedia.org/wiki/1969'; // default fallback URL

/**
 * Fetch and parse data from a URL.
 * @param {string} url - The URL to fetch.
 * @param {number} depth - Current recursion depth.
 * @param {number} maxDepth - Maximum recursion depth.
 * @param {Set<string>} visited - Set of visited URLs to avoid duplicates.
 * @returns {Promise<string[]>} Promise that resolves to an array of words parsed from the page and its linked pages.
 */
async function fetchData(url = DEFAULT_URL, depth = 2, maxDepth = 2, visited = new Set()) {
  // If we've already visited this URL, return empty to avoid loops
  if (visited.has(url)) {
    return [];
  }
  visited.add(url);

  try {
    const response = await axios.get(url);
    const html = response.data;
    const $ = cheerio.load(html);

    // Extract all text from the page
    // This might be too broad. You could refine to certain selectors.
    let textContent = $('body').text();
    // Normalize whitespace, remove empty lines, etc.
    textContent = textContent.replace(/\s+/g, ' ').trim();

    // Split into words
    let words = textContent.split(' ').filter(Boolean);

    // If we haven't hit maxDepth, follow links
    if (depth < maxDepth) {
      // Extract all links
      const links = $('a[href]')
        .map((i, el) => $(el).attr('href'))
        .get()
        .filter(href => href.startsWith('http')) // only follow absolute links to avoid complexity

      // For each link, recursively fetch data
      for (let link of links) {
        const linkWords = await fetchData(link, depth + 1, maxDepth, visited);
        words = words.concat(linkWords);
      }
    }

    return words;
  } catch (err) {
    // If fetch failed (no internet or any error), return empty array
    return [];
  }
}

module.exports = {
  fetchData
};

